#!/usr/bin/env python3
"""Assemble post-freeze research notes; never writes a transcription file.

Every substantive item is separately searched against every supplied context
document. Search hits are retrieval records, not assertions of mathematical
equivalence; the manually reviewed context field states the relationship.
"""
from pathlib import Path
import json, re, subprocess
from datetime import datetime, timezone

ROOT=Path(__file__).resolve().parent.parent
CTX=ROOT.parent/'context'
ITEMS=json.loads((ROOT/'records/research_context_early_items.json').read_text())

def edit(n,**kw):
    ITEMS[n-1].update(kw)

edit(6,body=r'''The asserted “équivalence des catégories” of algebraic and analytic constructible torsion sheaves needs its constructibility convention recovered. On $\mathbb C$, the finite-coefficient sheaf supported on the closed discrete analytic set $\mathbb Z=V(\sin\pi z)$ is locally constant on that set and its complement, but its support is not algebraically constructible in $\mathbb A^1_{\mathbb C}$. Two possibly disconnected analytic strata already suffice; a connected-stratum convention instead allows a locally finite point stratification. This conditional support test leaves intact narrower comparison categories, such as finite local systems.''',confidence='High for the support obstruction; applicability remains conditional on the historical analytic-constructibility convention.',source='Artin (1973a), SGA 4 XI, Theorem 4.4: a narrower finite locally constant comparison; no identification of all analytic constructible sheaves.')
edit(26,body=r'''“Alors la suite spectrale implique” uses vanishing below $2d$ to identify $H^{2d}_Y(X,F)$ with global sections of $\underline H^{2d}_Y(F)$, yielding a supported global class. The separate Kummer NB is conditional on a global $\beta\in H^1_Y(X,G_m)$, with the word “si” itself doubtful; its boundary in $H^2_Y(X,\mu_n)$ maps to zero in $H^2_Y(X,G_m)$. That degree-two assertion must not be extended to every higher-codimension fundamental class. The edge isomorphism and the conditional Kummer observation therefore have different hypotheses and proof mechanisms.''')
edit(18,source='The Stacks Project Authors (n.d.), §59.63, Tag 0A3J, for the Artin–Schreier sequence; the punctured-stalk calculation here is our own.')

